values.value:
{
  "type": "object",
  "properties": {
    "clientName": {
      "type": "string",
      "description": "Pre-fill the client name in KYC and Loan forms."
    },
    "clientId": {
      "type": "string",
      "description": "CRM client identifier shown in the card header."
    },
    "startDate": {
      "type": "string",
      "format": "date",
      "description": "Process start date (YYYY-MM-DD). Defaults to today."
    },
    "initialTab": {
      "type": "string",
      "enum": ["kyc", "loan", "flow"],
      "description": "Tab to open on load.",
      "default": "kyc"
    },
    "loanAmount": {
      "type": "integer",
      "description": "Pre-fill loan amount in euros."
    }
  }
}
